<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/private/AdminStore.php';
if(getenv('OSMON_TEST_DATABASE')!=='osmon_test'){fwrite(STDERR,"Dedicated osmon_test required\n");exit(1);}
$c=['host'=>getenv('OSMON_TEST_HOST')?:'127.0.0.1','port'=>(int)(getenv('OSMON_TEST_PORT')?:3306),'database'=>'osmon_test','username'=>getenv('OSMON_TEST_USER')?:'root','password'=>getenv('OSMON_TEST_PASSWORD')?:'test-only'];
$db=connectFamily($c);$now=1000000.0;$key=str_repeat('k',32);$secret='12345678901234567890';$password='Test-only-password-123';
$clock=static function()use(&$now){return $now;};$admin=new AdminStore($db,$key,$clock);$family=new FamilyStore($db,$clock);
function check(bool $ok,string $text='Assertion failed'):void{if(!$ok)throw new RuntimeException($text);}
function errorStatus(int $status,Closure $fn):void{try{$fn();}catch(FamilyAPIError $e){check($e->status===$status,'Unexpected status '.$e->status);return;}throw new RuntimeException('Missing rejection '.$status);}
function otp():string{global $secret,$now;return totpCode($secret,(int)floor($now/30));}
function setupAdmin():array{
 global $db,$admin,$now,$secret,$password;$now=1000000.0;
 foreach(['osmon_admin_sessions','osmon_admins','osmon_admin_audit','osmon_devices','osmon_parents','osmon_rates']as$table)$db->exec('DELETE FROM '.$table);
 $admin->provision('operator',$password,$secret,otp());$now+=30;
 return $admin->login(['username'=>'operator','password'=>$password,'code'=>otp()]);
}
function action(string $m,string $path,array $body=[]):array{global $admin,$session;return $admin->dispatch($m,$path,$session['token'],$body,$session['csrf']);}
function makeFamily():array{
 global $family;
 $p=$family->dispatch('POST','/v1/parents','',[])['token'];$pair=$family->dispatch('POST','/v1/pairings','',['name'=>'PRIVATE_ALIAS','config'=>['limit'=>2,'tasks'=>[['id'=>newUUID(),'title'=>'PRIVATE_TASK','repeat'=>'daily']]]]);
 $family->dispatch('POST','/v1/claims',$p,['code'=>$pair['code']]);$d=$family->dispatch('GET','/v1/device',$pair['token'],[]);return [$p,$pair,$d];
}
$tests=[];
$tests['RFC 6238 fixed vectors and base32']=function(){global$secret;foreach([59=>'94287082',1111111109=>'07081804',1111111111=>'14050471',1234567890=>'89005924',2000000000=>'69279037',20000000000=>'65353130']as$t=>$code)check(totpCode($secret,(int)floor($t/30),8)===$code);check(base32Decode(base32Encode($secret))===$secret);};
$tests['encrypted seed binds identity and key']=function(){global$key,$secret;$sealed=encryptAdminSecret($secret,$key,'admin-one');check(!str_contains($sealed,$secret));check(decryptAdminSecret($sealed,$key,'admin-one')===$secret);foreach([[str_repeat('x',32),'admin-one'],[$key,'admin-two']]as[$k,$id]){try{decryptAdminSecret($sealed,$k,$id);throw new LogicException('Secret accepted');}catch(RuntimeException $e){check(!$e instanceof LogicException);}}};
$tests['second factor and code replay']=function(){global$session,$admin,$password,$now;$session=setupAdmin();errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>$password,'code'=>otp()]));$now+=30;errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>'wrong','code'=>otp()]));errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>$password,'code'=>'000000']));check($admin->login(['username'=>'operator','password'=>$password,'code'=>otp()])['username']==='operator');};
$tests['admin and parent roles isolated']=function(){global$session,$admin,$family;$session=setupAdmin();[$p]=makeFamily();errorStatus(401,fn()=>$admin->dispatch('GET','/admin-api/overview',$p,[]));errorStatus(401,fn()=>$family->dispatch('GET','/v1/children',$session['token'],[]));check(action('GET','/admin-api/status')['authenticated']);};
$tests['CSRF mandatory for actions']=function(){global$session,$admin;$session=setupAdmin();errorStatus(403,fn()=>$admin->dispatch('POST','/admin-api/families',$session['token'],['page'=>0],''));check(is_array(action('POST','/admin-api/families',['page'=>0])['families']));};
$tests['metadata never contains family payload or tokens']=function(){global$session,$family,$now;$session=setupAdmin();[$p,$pair,$d]=makeFamily();$family->dispatch('POST','/v1/device/location',$pair['token'],['latitude'=>53.123456,'longitude'=>10.654321,'accuracy'=>1,'measured'=>$now]);$list=action('POST','/admin-api/families',['page'=>0]);$ref=$list['families'][0]['id'];$data=encodeJSON([action('GET','/admin-api/overview'),$list,action('GET','/admin-api/families/'.$ref.'/devices'),action('GET','/admin-api/audit')]);foreach([$p,$pair['token'],tokenHash($p),tokenHash($pair['token']),'PRIVATE_TASK','PRIVATE_ALIAS','53.123456','10.654321','locationRequest','locationSharing']as$v)check(!str_contains($data,$v),'Private data leaked');};
$tests['suspend rejects native and browser and clears location']=function(){global$session,$family,$now;$session=setupAdmin();[$p,$pair,$d]=makeFamily();$code=$family->dispatch('POST','/v1/web-codes',$p,[])['code'];$web=$family->dispatch('POST','/v1/web-codes/redeem','',['code'=>$code])['token'];$family->dispatch('PUT','/v1/device/location-sharing',$pair['token'],['enabled'=>true]);$family->dispatch('POST','/v1/device/location',$pair['token'],['latitude'=>53,'longitude'=>10,'accuracy'=>50,'measured'=>$now]);$ref=action('POST','/admin-api/families',['page'=>0])['families'][0]['id'];errorStatus(400,fn()=>action('POST','/admin-api/families/'.$ref.'/suspend',[]));action('POST','/admin-api/families/'.$ref.'/suspend',['confirm'=>$ref]);foreach([$p,$web]as$t)errorStatus(401,fn()=>$family->dispatch('GET','/v1/children',$t,[]));errorStatus(401,fn()=>$family->dispatch('GET','/v1/device',$pair['token'],[]));action('POST','/admin-api/families/'.$ref.'/resume',['confirm'=>$ref]);$v=$family->dispatch('GET','/v1/device',$pair['token'],[]);check($v['location']===null&&!$v['locationSharing']);errorStatus(401,fn()=>$family->dispatch('GET','/v1/children',$web,[]));};
$tests['delete family cascades and audits']=function(){global$session,$family,$db;$session=setupAdmin();[$p,$pair]=makeFamily();$ref=action('POST','/admin-api/families',['page'=>0])['families'][0]['id'];action('DELETE','/admin-api/families/'.$ref,['confirm'=>$ref]);errorStatus(401,fn()=>$family->dispatch('GET','/v1/device',$pair['token'],[]));check((int)$db->query('SELECT count(*) FROM osmon_devices')->fetchColumn()===0);check(action('GET','/admin-api/audit')['events'][0]['action']==='family_deleted');};
$tests['unlink device keeps family and audits']=function(){global$session,$family;$session=setupAdmin();[$p,$pair,$d]=makeFamily();action('DELETE','/admin-api/devices/'.$d['id'],['confirm'=>$d['id']]);check($family->dispatch('GET','/v1/children',$p,[])['children']===[]);check(action('GET','/admin-api/audit')['events'][0]['action']==='device_unlinked');};
$tests['idle expiry and absolute expiry']=function(){global$session,$now;$session=setupAdmin();$now+=1801;errorStatus(401,fn()=>action('GET','/admin-api/status'));$session=setupAdmin();for($i=0;$i<4;$i++){$now+=1700;action('GET','/admin-api/status');}$now+=401;errorStatus(401,fn()=>action('GET','/admin-api/status'));};
$tests['logout and new login revoke old session']=function(){global$session,$admin,$password,$now;$session=setupAdmin();$old=$session['token'];$now+=30;$session=$admin->login(['username'=>'operator','password'=>$password,'code'=>otp()]);errorStatus(401,fn()=>$admin->dispatch('GET','/admin-api/status',$old,[]));action('DELETE','/admin-api/logout');errorStatus(401,fn()=>action('GET','/admin-api/status'));};
$tests['account lock persists then expires']=function(){global$session,$admin,$password,$now;$session=setupAdmin();for($i=0;$i<5;$i++)errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>'wrong','code'=>otp()]));$now+=30;errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>$password,'code'=>otp()]));$now+=901;check($admin->login(['username'=>'operator','password'=>$password,'code'=>otp()])['username']==='operator');};
$tests['CLI reset invalidates session']=function(){global$session,$admin,$secret,$password,$now;$session=setupAdmin();$now+=30;$admin->provision('operator',$password,$secret,otp());errorStatus(401,fn()=>action('GET','/admin-api/status'));errorStatus(401,fn()=>$admin->login(['username'=>'operator','password'=>$password,'code'=>otp()]));};
$tests['audit expires and admin rate limit']=function(){global$session,$now,$family,$db;$session=setupAdmin();$now+=90*86400+1;$family->cleanup();check((int)$db->query('SELECT count(*) FROM osmon_admin_audit')->fetchColumn()===0);for($i=0;$i<5;$i++)$family->rate('192.0.2.10','/admin-api/login',str_repeat('a',64));errorStatus(429,fn()=>$family->rate('192.0.2.10','/admin-api/login',str_repeat('a',64)));};
$tests['mail settings require admin session and CSRF']=function(){global$session,$admin;$session=setupAdmin();foreach([['GET','/admin-api/mail'],['PUT','/admin-api/mail'],['POST','/admin-api/mail/test']]as[$m,$p]){errorStatus(401,fn()=>$admin->dispatch($m,$p,'',[]));if($m!=='GET')errorStatus(403,fn()=>$admin->dispatch($m,$p,$session['token'],[],''));check(action($m,$p)['mailAuthorized']);}};
$failed=0;foreach($tests as$name=>$test){try{$test();echo"PASS $name\n";}catch(Throwable$e){$failed++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}echo count($tests)." admin tests, $failed failures\n";exit($failed?1:0);
